import{_ as s,o as t,c as a,a0 as n}from"./chunks/framework.Bmhw_dvp.js";const u=JSON.parse('{"title":"Operational Lessons Learned","description":"Component of the Agentic Development Framework documentation.","frontmatter":{"type":"Agentic Development Framework","title":"Operational Lessons Learned","description":"Component of the Agentic Development Framework documentation.","tags":["framework","internal"],"isInternal":true},"headers":[],"relativePath":"framework/lessons-learned.md","filePath":"framework/lessons-learned.md"}'),o={name:"framework/lessons-learned.md"};function i(r,e,l,d,c,p){return t(),a("div",null,[...e[0]||(e[0]=[n(`<h2 id="_5-operational-lessons-learned" tabindex="-1">5. Operational Lessons Learned <a class="header-anchor" href="#_5-operational-lessons-learned" aria-label="Permalink to &quot;5. Operational Lessons Learned&quot;">​</a></h2><p>The following lessons were discovered during production development and are offered as warnings to adopters.</p><h3 id="lesson-1-monorepo-workspaces-break-ci-silently" tabindex="-1">Lesson 1: Monorepo Workspaces Break CI Silently <a class="header-anchor" href="#lesson-1-monorepo-workspaces-break-ci-silently" aria-label="Permalink to &quot;Lesson 1: Monorepo Workspaces Break CI Silently&quot;">​</a></h3><p><strong>Context:</strong> A monorepo with a shared types workspace (<code>@project/shared</code>) used by both frontend and backend.</p><p><strong>Problem:</strong> CI pipelines that run <code>npm ci</code> expect all packages to be published to a registry. A local workspace that has never been published to npm causes a <code>404 Not Found</code> error during Cloud Functions deployment.</p><p><strong>Solution:</strong> Add a <code>predeploy</code> hook that runs <code>npm pack</code> on the shared workspace to generate a local tarball, then reference that tarball in <code>package.json</code> instead of a semver range.</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// firebase.json</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;functions&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;predeploy&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;npm pack --workspace=shared --pack-destination=functions/&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] } }</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// functions/package.json</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;dependencies&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;@project/shared&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;file:./project-shared-1.0.0.tgz&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } }</span></span></code></pre></div><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Additionally, <code>npm ci</code> causes <code>EINTEGRITY</code> checksum failures when installing local tarballs generated on-the-fly. Use <code>npm install</code> instead of <code>npm ci</code> in GitHub Actions workflows that use dynamic tarballs.</p></div><h3 id="lesson-2-stale-planning-documents-cause-feature-duplication" tabindex="-1">Lesson 2: Stale Planning Documents Cause Feature Duplication <a class="header-anchor" href="#lesson-2-stale-planning-documents-cause-feature-duplication" aria-label="Permalink to &quot;Lesson 2: Stale Planning Documents Cause Feature Duplication&quot;">​</a></h3><p><strong>Context:</strong> A <code>features_backlog.md</code> file listed &quot;Usage Dashboard&quot; as a pending feature.</p><p><strong>Solution:</strong> Separate planning documents into a strict 3-file structure:</p><ol><li><strong><code>implementation_status.md</code></strong> — ONLY active and upcoming work items. When a task is completed, remove it.</li><li><strong><code>features_backlog.md</code></strong> — ONLY pending features, prioritised by tier. No strikethrough &quot;done&quot; items.</li><li><strong><code>changelog.md</code></strong> — Archive of ALL completed features. Include an explicit AI instruction at the top: &quot;Do NOT read this file during active development.&quot;</li></ol><p>The agent rules file must codify this pattern, and the knowledge harvesting workflow must include a mandatory &quot;archive completed features&quot; step. This reduces the active planning documents from ~130 lines to ~45 lines — saving ~700 tokens per read and eliminating the risk of feature duplication.</p><h3 id="lesson-3-signinwithredirect-fails-silently-in-local-development" tabindex="-1">Lesson 3: <code>signInWithRedirect</code> Fails Silently in Local Development <a class="header-anchor" href="#lesson-3-signinwithredirect-fails-silently-in-local-development" aria-label="Permalink to &quot;Lesson 3: \`signInWithRedirect\` Fails Silently in Local Development&quot;">​</a></h3><p><strong>Context:</strong> Firebase Authentication OAuth flow using <code>signInWithRedirect</code> for YouTube integration.</p><p><strong>Problem:</strong> The redirect bounces through <code>firebaseapp.com</code>, and <code>sessionStorage</code> context is lost on <code>localhost</code>, causing <code>getRedirectResult()</code> to return <code>null</code> with no error.</p><p><strong>Solution:</strong> Use <code>signInWithPopup</code> exclusively. It works in all environments and is not blocked by popup blockers when triggered by a direct user click. This was documented as an Architecture Decision Record and cross-referenced in the agent rules file, ensuring no future agent attempts to revert to <code>signInWithRedirect</code>.</p><h3 id="lesson-4-firebase-emulators-process-state-transitions-instantly" tabindex="-1">Lesson 4: Firebase Emulators Process State Transitions Instantly <a class="header-anchor" href="#lesson-4-firebase-emulators-process-state-transitions-instantly" aria-label="Permalink to &quot;Lesson 4: Firebase Emulators Process State Transitions Instantly&quot;">​</a></h3><p><strong>Context:</strong> E2E tests asserting that a workflow step is in the <code>queued</code> state after a Firestore write.</p><p><strong>Problem:</strong> The emulator&#39;s Cloud Functions execute instantly (unlike production, which has cold-start latency). By the time Playwright reads the document, the backend has already processed the state through <code>queued → running → error</code>.</p><p><strong>Solution:</strong> Never assert on intermediate states. Accept any downstream state:</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ✅ Accept any downstream state</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">expect</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">([</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;queued&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;running&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;error&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;complete&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]).</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">toContain</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    data?.workflowState?.step_publish?.status</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><h3 id="lesson-5-security-rules-crash-on-missing-fields" tabindex="-1">Lesson 5: Security Rules Crash on Missing Fields <a class="header-anchor" href="#lesson-5-security-rules-crash-on-missing-fields" aria-label="Permalink to &quot;Lesson 5: Security Rules Crash on Missing Fields&quot;">​</a></h3><p><strong>Context:</strong> Firestore security rules validating that a user&#39;s <code>plan</code> field hasn&#39;t been tampered with during an update.</p><p><strong>Problem:</strong> New users don&#39;t have a <code>plan</code> field yet. The rule <code>request.resource.data.plan == resource.data.plan</code> crashes with a &quot;missing property&quot; error, which Firebase interprets as <code>false</code> (access denied).</p><p><strong>Solution:</strong> Always use <code>.get(&#39;field&#39;, defaultValue)</code> in Firestore security rules:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// ✅ Safe: handles missing fields gracefully</span></span>
<span class="line"><span>request.resource.data.get(&#39;plan&#39;, null) == resource.data.get(&#39;plan&#39;, null)</span></span></code></pre></div><h3 id="lesson-6-silent-e2e-breakage-from-ui-structural-changes" tabindex="-1">Lesson 6: Silent E2E Breakage from UI Structural Changes <a class="header-anchor" href="#lesson-6-silent-e2e-breakage-from-ui-structural-changes" aria-label="Permalink to &quot;Lesson 6: Silent E2E Breakage from UI Structural Changes&quot;">​</a></h3><p><strong>Context:</strong> The agent moves an existing UI element (e.g., a &quot;Settings&quot; button) into a new dropdown menu (&quot;More Actions&quot;) to clean up the interface.</p><p><strong>Problem:</strong> The UI looks great, but the Playwright E2E tests suddenly timeout and fail in CI because <code>locator(&#39;button:has-text(&quot;Settings&quot;)&#39;)</code> is no longer visible on the page without first clicking the dropdown. The agent deployed the code without testing it locally, breaking the build.</p><p><strong>Solution:</strong> &quot;Documentation First&quot; must also apply to E2E tests. Whenever an agent renames, moves, or obscures a UI element, they MUST use <code>grep_search</code> to find dependent locators in <code>frontend/e2e/</code> and update the tests alongside the UI change. Furthermore, all deployments to <code>staging</code> or <code>production</code> MUST be preceded by a local emulator test run (<code>npx playwright test</code>) and explicit user approval.</p><hr>`,32)])])}const g=s(o,[["render",i]]);export{u as __pageData,g as default};
